**Gates before launch**

I run six gates before the full run. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are committed and unchanged since that commit. This proves the predictions were fixed before any result existed. Second, I check the script against the approved plan line by line. That means configs B and C2, 50 tickets, 5 trials per cell, grade.py, judge.md, and the $40 cap. Third, I give grade.py two hand-made outputs. One matches answers.json and one does not. It must score them 1 and 0. Fourth, I copy the per-run command from spe/evals/harness/r03-workflow.js into `args.runner`. I can't read that file in this trial, so the command has to be checked against the real file. Fifth, I launch with `pilot: true` on 2 tickets and 1 trial to measure the real cost of one run and one judge call. The full run makes 500 subject runs and 500 judge calls. A $40 cap leaves about 4 cents per call, which is probably too little for Opus. If the pilot projects more than $40, I stop and bring it back to you. I won't cut tickets or trials on my own, because that would change the approved plan. The script checks the cap against the pilot estimates, not against the real bill, so I also check the bill after the run. Last, I save the script as spe/evals/harness/r04-workflow.js and commit it locally, as the loop asks, before launch.

**Script**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4. Configs B and C2 on 50 tickets, 5 trials per cell. Code grader checks label.category and label.priority. Opus judge scores reply tone. $40 spend cap.',
  phases: [
    { title: 'Preflight' },
    { title: 'Run and judge' },
    { title: 'Grade' },
    { title: 'Summary' },
  ],
}

// Things this script cannot check by itself, because it has no filesystem access:
// 1. args.runner is the per-run command from spe/evals/harness/r03-workflow.js.
//    It must accept --config, --ticket, --trial, --out and write one JSON output file
//    that holds the reply text and the label (label.category, label.priority).
// 2. args.estRunUsd, args.estJudgeUsd, args.estOverheadUsd come from a pilot run.
//    The cap is checked against these estimates, not against billed spend.

const CONFIGS = ['B', 'C2']
const PLAN = { tickets: 50, trials: 5, capUsd: 40 }

const a = args ?? {}
const pilot = a.pilot === true
const TRIALS = pilot ? (a.trials ?? 1) : PLAN.trials
const LIMIT = pilot ? (a.limit ?? 2) : PLAN.tickets
const CAP_USD = PLAN.capUsd
const RUN_DIR = a.runDir ?? (pilot ? 'spe/evals/runs/r04-pilot' : 'spe/evals/runs/r04')
const SUBJECT_MODEL = a.model ?? 'opus'
const EST_RUN = Number(a.estRunUsd ?? 0)
const EST_JUDGE = Number(a.estJudgeUsd ?? 0)
const EST_OVERHEAD = Number(a.estOverheadUsd ?? 0)

if (!a.runner) {
  throw new Error('args.runner is required. Copy the per-run command from spe/evals/harness/r03-workflow.js.')
}
if (!pilot && !(EST_RUN > 0 && EST_JUDGE > 0)) {
  throw new Error('args.estRunUsd and args.estJudgeUsd are required for the full run. Measure them with a pilot first.')
}
if (pilot) log(`PILOT MODE: ${LIMIT} tickets, ${TRIALS} trial(s), output in ${RUN_DIR}. Not a plan-conformant run.`)

let reserved = 0
function reserve(usd) {
  if (reserved + usd > CAP_USD) return false
  reserved += usd
  return true
}

const outPath = (c) => `${RUN_DIR}/${c.config}/${c.ticket}/t${c.trial}.json`

// ---------------- Preflight ----------------
phase('Preflight')

const PRE_SCHEMA = {
  type: 'object',
  required: ['ticketIds', 'dirtyLines', 'predictionsCommit', 'planCommit', 'gradersPresent'],
  properties: {
    ticketIds: { type: 'array', items: { type: 'string' } },
    dirtyLines: { type: 'array', items: { type: 'string' } },
    predictionsCommit: { type: 'string' },
    planCommit: { type: 'string' },
    gradersPresent: { type: 'boolean' },
  },
}

const pre = await agent(
`You are the preflight check for SPE round 4. Do not edit, stage, or commit any file. Report facts only.
1. Read spe/evals/tasks/answers.json. Return every ticket ID in file order. Do not return any labels.
2. Run: git status --porcelain -- spe/predictions/r04.yaml spe/plans/r04.md spe/evals/graders/grade.py spe/evals/graders/judge.md spe/evals/tasks/answers.json
   Return every line it prints in dirtyLines. Return an empty list if it prints nothing.
3. Run: git log -1 --format=%H -- spe/predictions/r04.yaml   Return the hash as predictionsCommit.
4. Run: git log -1 --format=%H -- spe/plans/r04.md   Return the hash as planCommit.
5. Set gradersPresent to true only if both spe/evals/graders/grade.py and spe/evals/graders/judge.md exist.`,
  { label: 'preflight', phase: 'Preflight', model: 'opus', schema: PRE_SCHEMA },
)

if (pre.dirtyLines.length > 0) throw new Error(`Pre-registered or grader files have uncommitted changes: ${pre.dirtyLines.join(' | ')}`)
if (!pre.predictionsCommit || !pre.planCommit) throw new Error('r04 predictions or plan are not committed.')
if (!pre.gradersPresent) throw new Error('grade.py or judge.md is missing.')
if (!pilot && pre.ticketIds.length !== PLAN.tickets) {
  throw new Error(`Plan says ${PLAN.tickets} tickets. answers.json has ${pre.ticketIds.length}.`)
}

const tickets = pre.ticketIds.slice(0, LIMIT)

// Interleave configs and flip their order per ticket, so drift over time hits both configs.
const cells = []
let k = 0
for (let trial = 1; trial <= TRIALS; trial++) {
  tickets.forEach((ticket, i) => {
    const order = (trial + i) % 2 === 0 ? CONFIGS : [...CONFIGS].reverse()
    for (const config of order) {
      cells.push({ id: `c${String(++k).padStart(4, '0')}`, config, ticket, trial })
    }
  })
}

const projected = cells.length * (EST_RUN + EST_JUDGE) + EST_OVERHEAD
log(`Cells: ${cells.length}. Projected estimated spend: $${projected.toFixed(2)} of $${CAP_USD} cap.`)
if (!pilot && projected > CAP_USD) {
  throw new Error(`Projected $${projected.toFixed(2)} is over the $${CAP_USD} cap. Stop and take this back to the user. Do not cut the plan silently.`)
}
reserve(EST_OVERHEAD)

// ---------------- Run and judge ----------------
phase('Run and judge')

const RUN_SCHEMA = {
  type: 'object',
  required: ['exitCode', 'reply', 'error'],
  properties: {
    exitCode: { type: 'number' },
    reply: { type: 'string' },
    error: { type: 'string' },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['score', 'rationale'],
  properties: {
    score: { type: 'number' },
    rationale: { type: 'string' },
  },
}

const runStage = async (cell) => {
  if (!reserve(EST_RUN)) return { ...cell, status: 'skipped_cap' }
  const out = outPath(cell)
  const r = await agent(
`Run one command from the repository root and report the result.
Do not edit any file. Do not open spe/evals/tasks/answers.json. Do not retry if the command fails.
Command:
${a.runner} --config ${cell.config} --ticket ${cell.ticket} --trial ${cell.trial} --out ${out}
When it exits, read ${out}. Return the exit code, the reply text exactly as written in that file, and the error text if there is one. Use an empty string for missing values.`,
    { label: `run ${cell.id}`, phase: 'Run and judge', model: SUBJECT_MODEL, schema: RUN_SCHEMA },
  )
  return { ...cell, out, status: r.exitCode === 0 && r.reply ? 'ok' : 'run_error', ...r }
}

const judgeStage = async (r) => {
  if (r.status !== 'ok') return { ...r, tone: null }
  if (!reserve(EST_JUDGE)) return { ...r, tone: null, judgeStatus: 'skipped_cap' }
  // The judge sees the ticket ID and the reply only. It is not told the config.
  const j = await agent(
`You are the tone judge for a support-ticket eval.
Read spe/evals/graders/judge.md and apply its rubric exactly.
Find the text of ticket ${r.ticket} under spe/evals/tasks/. Do not open answers.json.
Judge only the reply below. Do not edit any file.

REPLY:
<<<
${r.reply}
>>>`,
    { label: `judge ${r.id}`, phase: 'Run and judge', model: 'opus', schema: JUDGE_SCHEMA },
  )
  return { ...r, tone: j.score, toneRationale: j.rationale, judgeStatus: 'ok' }
}

const results = await pipeline(cells, runStage, judgeStage)

const runErrors = results.filter((r) => r.status === 'run_error').length
const capSkips = results.filter((r) => r.status === 'skipped_cap' || r.judgeStatus === 'skipped_cap').length
log(`Runs done. Run errors: ${runErrors}. Cap skips: ${capSkips}. Estimated reserved: $${reserved.toFixed(2)}.`)

// ---------------- Grade ----------------
phase('Grade')

const GRADE_SCHEMA = {
  type: 'object',
  required: ['command', 'error', 'records'],
  properties: {
    command: { type: 'string' },
    error: { type: 'string' },
    records: {
      type: 'array',
      items: {
        type: 'object',
        required: ['path', 'categoryCorrect', 'priorityCorrect'],
        properties: {
          path: { type: 'string' },
          categoryCorrect: { type: 'boolean' },
          priorityCorrect: { type: 'boolean' },
        },
      },
    },
  },
}

const okPaths = results.filter((r) => r.status === 'ok').map((r) => r.out)

const graded = await agent(
`Run the code grader for SPE round 4. Do not edit grade.py, answers.json, or any output file.
1. Read spe/evals/graders/grade.py to learn how to call it.
2. Run it on each of the output files listed below against spe/evals/tasks/answers.json.
3. Return one record per file with its path and whether label.category and label.priority matched, exactly as grade.py reports. Do not judge anything yourself.
4. Return the exact command(s) you ran. If grade.py fails, return its error text and an empty records list.

FILES:
${okPaths.join('\n')}`,
  { label: 'grade', phase: 'Grade', model: 'opus', schema: GRADE_SCHEMA },
)

if (graded.error) throw new Error(`grade.py failed: ${graded.error}`)

const byPath = new Map(graded.records.map((g) => [g.path, g]))
const missing = okPaths.filter((p) => !byPath.has(p))
if (missing.length) log(`WARNING: ${missing.length} output files have no grade record.`)

// ---------------- Summary ----------------
phase('Summary')

const mean = (xs) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null)

const summary = {}
for (const config of CONFIGS) {
  const rows = results.filter((r) => r.config === config)
  const gradedRows = rows.map((r) => byPath.get(r.out)).filter(Boolean)
  const tones = rows.map((r) => r.tone).filter((t) => typeof t === 'number')
  summary[config] = {
    cells: rows.length,
    runErrors: rows.filter((r) => r.status === 'run_error').length,
    capSkips: rows.filter((r) => r.status === 'skipped_cap').length,
    graded: gradedRows.length,
    categoryAcc: mean(gradedRows.map((g) => (g.categoryCorrect ? 1 : 0))),
    priorityAcc: mean(gradedRows.map((g) => (g.priorityCorrect ? 1 : 0))),
    bothAcc: mean(gradedRows.map((g) => (g.categoryCorrect && g.priorityCorrect ? 1 : 0))),
    toneMean: mean(tones),
    toneN: tones.length,
  }
}

for (const config of CONFIGS) {
  const s = summary[config]
  log(`${config}: category ${s.categoryAcc}, priority ${s.priorityAcc}, both ${s.bothAcc}, tone ${s.toneMean} (n=${s.toneN}), errors ${s.runErrors}`)
}
log('Scoring against spe/predictions/r04.yaml is the next SPE step. This script does not do it.')

return {
  round: 4,
  pilot,
  runDir: RUN_DIR,
  predictionsCommit: pre.predictionsCommit,
  planCommit: pre.planCommit,
  gradeCommand: graded.command,
  estimatedSpendUsd: Number(reserved.toFixed(2)),
  capUsd: CAP_USD,
  spendNote: 'Estimated from pilot unit costs. Check billed spend.',
  summary,
  cells: results.map((r) => {
    const g = byPath.get(r.out)
    return {
      id: r.id, config: r.config, ticket: r.ticket, trial: r.trial, status: r.status,
      categoryCorrect: g ? g.categoryCorrect : null,
      priorityCorrect: g ? g.priorityCorrect : null,
      tone: r.tone ?? null,
      error: r.error || null,
    }
  }),
}
```
